/* Encomendas — aplicativo estático para GitHub Pages + Supabase */
(() => {
  "use strict";

  const CONFIG = window.APP_CONFIG || {};
  const DEMO = new URLSearchParams(location.search).get("demo") === "1";
  const CONFIGURED = /^https:\/\/.+\.supabase\.co$/.test(CONFIG.SUPABASE_URL || "") && !String(CONFIG.SUPABASE_ANON_KEY || "").includes("COLE_");
  const $ = (q, root = document) => root.querySelector(q);
  const $$ = (q, root = document) => [...root.querySelectorAll(q)];
  const app = $("#app");
  const today = () => new Date().toISOString().slice(0, 10);
  const n = (v) => { if (v === null || v === undefined || v === "") return 0; const x = typeof v === "number" ? v : Number(String(v).replace(/\./g, "").replace(",", ".")); return Number.isFinite(x) ? x : 0; };
  const dbNum = (v) => v === "" || v === null || v === undefined ? null : n(v);
  const esc = (v = "") => String(v).replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
  const fmtDate = (v) => !v ? "—" : new Intl.DateTimeFormat("pt-BR", {timeZone:"UTC"}).format(new Date(`${v}T12:00:00Z`));
  const fmtMoney = (v, cur = "BRL") => new Intl.NumberFormat("pt-BR", {style:"currency",currency:cur,currencyDisplay:cur === "USD" ? "narrowSymbol" : "symbol"}).format(n(v)).replace("US$", "$ ");
  const fmtNum = (v, max = 2) => new Intl.NumberFormat("pt-BR", {maximumFractionDigits:max}).format(n(v));
  const addDays = (date, days) => { if (!date || !days) return ""; const d = new Date(`${date}T12:00:00`); d.setDate(d.getDate() + Number(days)); return d.toISOString().slice(0,10); };
  const uid = () => `tmp_${Math.random().toString(36).slice(2)}`;
  const slug = (s) => String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const showToast = (msg, error = false) => { const el = $("#toast"); el.textContent = msg; el.className = `toast show${error ? " error" : ""}`; clearTimeout(showToast.t); showToast.t = setTimeout(() => el.className = "toast", 3200); };
  const setLoading = (on) => { let el = $(".loading-bar"); if (on && !el) { el = document.createElement("div"); el.className = "loading-bar"; document.body.append(el); } if (!on && el) el.remove(); };
  const statusLabels = {cotacao:"Cotação",confirmado:"Confirmado",em_producao:"Em produção",enviado:"Enviado",recebido_parcial:"Recebido parcial",recebido:"Recebido",finalizado:"Finalizado",cancelado:"Cancelado"};
  const trackingLabels = {aguardando_postagem:"Aguardando postagem",postado:"Postado",em_transito:"Em trânsito",fiscalizacao:"Fiscalização",aguardando_pagamento:"Aguardando pagamento",saiu_entrega:"Saiu para entrega",entregue:"Entregue",devolvido:"Devolvido",extraviado:"Extraviado"};
  const paymentLabels = {pendente:"Pendente",parcial:"Parcial",pago:"Pago",pago_a_mais:"Pago a mais"};
  const receiptLabels = {nao_recebido:"Não recebido",parcial:"Parcial",completo:"Completo",divergencia:"Com divergência"};
  const openStatuses = new Set(["cotacao","confirmado","em_producao","enviado","recebido_parcial"]);
  let supabase = null;
  let state = { session:null, profile:null, catalogs:{suppliers:[],products:[],transport_modes:[],carriers:[],payment_methods:[]}, rates:[], orders:[], filters:{}, route:"painel", detailTab:"resumo" };

  function rateFor(day = today()) {
    return state.rates.filter(r => r.day <= day).sort((a,b) => b.day.localeCompare(a.day))[0] || null;
  }
  function convert(amount, from, to, rate) { if (from === to) return n(amount); if (!n(rate)) return null; return from === "USD" ? n(amount)*n(rate) : n(amount)/n(rate); }
  function totals(o) {
    const cur = o.currency || "BRL", rate = n(o.exchange_rate) || null;
    const items = o.items || o.order_items || [], expenses = o.expenses || o.order_expenses || [], payments = o.payments || [], taxes = o.tax_payments || [];
    let missingRate = false;
    const cv = (amount, from, to, r = rate) => { const x = convert(amount, from, to, n(r) || rate); if (x === null) { missingRate = true; return 0; } return x; };
    const pieces = items.reduce((s,i) => s+n(i.total_pieces),0);
    const itemsTotal = items.reduce((s,i) => s+n(i.total_pieces)*n(i.unit_price),0);
    const supplierExpenses = expenses.filter(e=>e.charged_by_supplier).reduce((s,e)=>s+cv(e.amount,e.currency,cur),0);
    const supplierTotal = Math.round((itemsTotal+n(o.freight)-n(o.discount)+supplierExpenses)*100)/100;
    const paid = payments.reduce((s,p)=>s+cv(p.amount,p.currency,cur,p.exchange_rate),0);
    const pending = Math.round((supplierTotal-paid)*100)/100;
    const paymentStatus = pending < -.01 ? "pago_a_mais" : pending <= .01 ? "pago" : paid > 0 ? "parcial" : "pendente";
    const taxBRL = o.tax_mode === "por_fora" ? taxes.reduce((s,t)=>s+cv(t.amount,t.currency,"BRL",t.exchange_rate),0) : 0;
    const otherBRL = expenses.filter(e=>!e.charged_by_supplier).reduce((s,e)=>s+cv(e.amount,e.currency,"BRL"),0);
    const extrasPendingBRL = expenses.filter(e=>!e.charged_by_supplier&&!e.paid).reduce((s,e)=>s+cv(e.amount,e.currency,"BRL"),0);
    const paidBRL = payments.reduce((s,p)=>s+cv(p.amount,p.currency,"BRL",p.exchange_rate),0);
    const pendingBRL = cv(Math.max(pending,0),cur,"BRL");
    const landedBRL = paidBRL+pendingBRL+taxBRL+otherBRL;
    return {pieces,itemsTotal,supplierExpenses,supplierTotal,paid,pending,paymentStatus,taxBRL,otherBRL,extrasPendingBRL,paidBRL,pendingBRL,landedBRL,costPerPiece:pieces?landedBRL/pieces:null,taxAwaiting:o.tax_mode==="por_fora"&&!taxes.length,missingRate};
  }
  function receipt(o) {
    const items = o.items || o.order_items || [], tr = o.trackings || [];
    const expected = items.reduce((s,i)=>s+n(i.total_pieces),0), received = items.reduce((s,i)=>s+n(i.received_qty),0), defective = items.reduce((s,i)=>s+n(i.defective_qty),0);
    const checked = items.some(i=>i.received_qty !== null && i.received_qty !== undefined), packagesReceived = tr.filter(t=>t.received).length;
    let status = !checked&&!packagesReceived ? "nao_recebido" : defective>0||items.some(i=>n(i.received_qty)>n(i.total_pieces)) ? "divergencia" : items.length&&items.every(i=>n(i.received_qty)===n(i.total_pieces)) ? "completo" : "parcial";
    return {status,expected,received,defective,missing:Math.max(expected-received,0),packagesReceived,packagesTotal:tr.length};
  }
  const isAdmin = () => state.profile?.papel === "administrador" || DEMO;
  const tag = (text, color="") => `<span class="tag ${color}">${esc(text)}</span>`;
  const statusTag = s => tag(statusLabels[s]||s, ["finalizado","recebido"].includes(s)?"green":["cancelado"].includes(s)?"red":["cotacao","confirmado"].includes(s)?"blue":"amber");
  const payTag = s => tag(paymentLabels[s], s==="pago"?"green":s==="pago_a_mais"?"blue":s==="parcial"?"amber":"red");
  const receiptTag = s => tag(receiptLabels[s], s==="completo"?"green":s==="divergencia"?"red":s==="parcial"?"amber":"");

  const demoData = () => {
    const cat = {
      suppliers:[{id:1,name:"Shenzhen Tech Co.",contact:"Li Wei"},{id:2,name:"Yiwu Best Trade"},{id:3,name:"Xiamen Clothing"}],
      products:[{id:1,name:"Fones Bluetooth TWS"},{id:2,name:"Capas para celular"},{id:3,name:"Camisetas básicas"}],
      transport_modes:[{id:1,name:"Aéreo",default_days:20},{id:2,name:"Marítimo",default_days:55}],
      carriers:[{id:1,name:"17TRACK",tracking_url:"https://t.17track.net/pt#nums={code}"},{id:2,name:"DHL",tracking_url:"https://www.dhl.com/br-pt/home/rastreamento.html?tracking-id={code}"}],
      payment_methods:[{id:1,name:"Wise"},{id:2,name:"PIX"}]
    };
    const mk = (id,title,supplier,date,expected,status,pieces,price,paid=0,tax="sem") => ({id,title,supplier_id:supplier.id,supplier,order_date:date,expected_date:expected,transport_mode_id:1,transport_mode:cat.transport_modes[0],carrier_id:1,carrier:cat.carriers[0],currency:"USD",exchange_rate:5.42,freight:80,discount:0,tax_mode:tax,tax_amount:0,status,notes:"",needs_review:id===1003,items:[{id:id*10,product_id:1,product:cat.products[0],variant:"Masculino",total_pieces:pieces,unit_price:price,received_qty:null,defective_qty:0,sizes:{P:pieces/2,M:pieces/2},position:0}],expenses:[],payments:paid?[{id:id*20,paid_on:date,amount:paid,currency:"USD",exchange_rate:5.4,payment_method_id:1}]:[],tax_payments:[],trackings:[{id:id*30,code:`CN${id}BR`,carrier_id:1,carrier:cat.carriers[0],status:"em_transito",received:false}],created_at:`${date}T12:00:00Z`});
    state.profile={nome:"João",papel:"administrador"}; state.catalogs=cat; state.rates=[{day:today(),usd_brl:5.42},{day:"2026-09-20",usd_brl:5.35}];
    state.orders=[mk(1008,"Fones Bluetooth TWS",cat.suppliers[0],"2026-09-01","2026-09-21","enviado",600,2,600,"por_fora"),mk(1003,"Capas para celular",cat.suppliers[1],"2026-09-05","2026-09-25","em_producao",1200,.8,300),mk(1015,"Camisetas básicas",cat.suppliers[2],"2026-09-14","2026-10-04","confirmado",800,3.2,0),mk(1018,"Acessórios diversos",cat.suppliers[0],"2026-09-18","2026-10-08","confirmado",380,1.7,0)];
  };

  async function query(promise) { setLoading(true); try { const {data,error}=await promise; if(error) throw error; return data; } finally { setLoading(false); } }
  async function loadAll() {
    if (DEMO) { demoData(); return; }
    const userId = state.session.user.id;
    const [profile, suppliers, products, modes, carriers, methods, rates, orders] = await Promise.all([
      query(supabase.from("app_profiles").select("*").eq("user_id",userId).single()),
      query(supabase.from("suppliers").select("*").order("name")), query(supabase.from("products").select("*").order("name")),
      query(supabase.from("transport_modes").select("*").order("name")), query(supabase.from("carriers").select("*").order("name")),
      query(supabase.from("payment_methods").select("*").order("name")), query(supabase.from("exchange_rates").select("*").order("day",{ascending:false})),
      query(supabase.from("orders").select(`*,supplier:suppliers(*),transport_mode:transport_modes(*),carrier:carriers(*),items:order_items(*,product:products(*)),expenses:order_expenses(*),payments(*,method:payment_methods(*)),tax_payments(*),trackings(*,carrier:carriers(*))`).order("created_at",{ascending:false}))
    ]);
    state.profile=profile; state.catalogs={suppliers,products,transport_modes:modes,carriers,payment_methods:methods}; state.rates=rates; state.orders=orders;
  }

  function shell(content, active=state.route) {
    const r=rateFor(), fresh=r?.day===today();
    return `<header class="topbar"><div class="topbar-inner"><div class="brand">Encomendas</div><nav class="nav">${navLinks(active)}</nav><div class="top-meta"><span class="user-name">Olá, ${esc(state.profile?.nome||"usuário")}</span><button class="btn ghost small-btn" data-action="logout">Sair</button><span class="rate-top ${fresh?"":"stale"}" title="${fresh?"Cotação de hoje":"Usando a última cotação anterior"}">$ 1 = ${r?fmtMoney(r.usd_brl):"sem cotação"}</span></div></div></header><main class="page">${content}</main><nav class="bottom-nav">${mobileLinks(active)}</nav>`;
  }
  function navLinks(active){return [["painel","Painel"],["pedidos","Pedidos"],["novo","Novo pedido"],["dolar","Dólar"],["cadastros","Cadastros"]].map(([r,l])=>`<a href="#${r}" class="${active===r?"active":""}">${l}</a>`).join("");}
  function mobileLinks(active){return [["painel","⌂","Painel"],["pedidos","▤","Pedidos"],["novo","+","Novo"],["dolar","$","Dólar"],["cadastros","♙","Cadastros"]].map(([r,i,l])=>`<a href="#${r}" class="${active===r?"active":""} ${r==="novo"?"new":""}"><span>${i}</span>${l}</a>`).join("");}
  function pageHead(title, subtitle="", actions=""){return `<div class="page-head"><div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:""}</div><div class="head-actions">${actions}</div></div>`;}
  function renderLogin(message="") {
    app.innerHTML=`<div class="login-shell"><section class="login-art"><div class="brand" style="color:white">Encomendas</div><h1>Suas importações,<br>sob controle.</h1><p>Pedidos, pagamentos, rastreios e conferência em um só lugar.</p></section><section class="login-form-wrap"><form id="login-form" class="login-form"><h2>Entrar</h2><p class="muted">Use o e-mail e a senha cadastrados no Supabase.</p>${message?`<div class="alert error">${esc(message)}</div>`:""}<label class="field-label">E-mail<input class="field" name="email" type="email" autocomplete="email" required></label><label class="field-label" style="margin-top:14px">Senha<input class="field" name="password" type="password" autocomplete="current-password" required></label><button class="btn primary" type="submit">Entrar</button><p class="small muted" style="margin-top:20px">O acesso aos dados é protegido pelo Supabase Auth e pelas políticas RLS.</p></form></section></div>`;
  }
  function renderConfigHelp(){app.innerHTML=`<div class="login-shell"><section class="login-art"><h1>Falta uma configuração</h1><p>O aplicativo está pronto. Agora ele precisa saber qual projeto Supabase usar.</p></section><section class="login-form-wrap"><div class="login-form"><h2>Configure em 3 passos</h2><ol><li>Abra o arquivo <strong>config.js</strong>.</li><li>Cole a <strong>Project URL</strong> e a chave <strong>publishable/anon</strong> do Supabase.</li><li>Salve e recarregue esta página.</li></ol><div class="alert info">Não use a senha do banco nem a chave service_role.</div><a class="btn primary" href="?demo=1">Conhecer no modo demonstração</a></div></section></div>`;}

  function renderDashboard(){
    const orders=state.orders, current=rateFor(), rate=n(current?.usd_brl), open=orders.filter(o=>openStatuses.has(o.status)), late=open.filter(o=>o.expected_date&&o.expected_date<today()), pieces=open.reduce((s,o)=>s+receipt(o).missing,0);
    const payableBRL=open.reduce((s,o)=>{const t=totals(o);return s+(o.currency==="USD"?t.pending*rate:t.pending)},0); const pendingExpenses=orders.reduce((s,o)=>s+totals(o).extrasPendingBRL,0);
    const attention=orders.filter(o=>{const t=totals(o);return o.needs_review||t.taxAwaiting||(openStatuses.has(o.status)&&o.expected_date<today())}).slice(0,7);
    const in15=open.filter(o=>o.expected_date&&o.expected_date>=today()&&o.expected_date<=addDays(today(),15)).sort((a,b)=>a.expected_date.localeCompare(b.expected_date));
    const suppliers={}; open.forEach(o=>{const k=o.supplier?.name||"Sem fornecedor",t=totals(o);suppliers[k]=(suppliers[k]||0)+(o.currency==="USD"?t.pending*rate:t.pending)});
    const row=o=>{const t=totals(o);return `<tr><td><strong>${esc(o.title)}</strong><div class="small muted">#${o.id}</div></td><td>${esc(o.supplier?.name||"—")}</td><td class="${o.expected_date<today()&&openStatuses.has(o.status)?"danger-text":""}">${fmtDate(o.expected_date)}</td><td>${statusTag(o.status)}</td><td class="num">${fmtMoney(t.pending,o.currency)}</td><td><a href="#pedido/${o.id}">Ver</a></td></tr>`};
    const content=pageHead("Painel","Resumo das suas compras sob encomenda")+`<section class="grid kpis"><button class="kpi" data-filter-link="abertos"><span class="kpi-icon">▣</span><span><span class="kpi-label">A pagar</span><span class="kpi-value">${fmtMoney(payableBRL)}</span><span class="kpi-sub">${open.length} pedidos em aberto</span></span></button><button class="kpi" data-filter-link="abertos"><span class="kpi-icon">▤</span><span><span class="kpi-label">Pedidos em aberto</span><span class="kpi-value">${open.length}</span><span class="kpi-sub">Acompanhar produção e envio</span></span></button><button class="kpi good" data-filter-link="receber"><span class="kpi-icon">◇</span><span><span class="kpi-label">Peças a receber</span><span class="kpi-value">${fmtNum(pieces,0)}</span><span class="kpi-sub">em ${open.filter(o=>receipt(o).missing>0).length} pedidos</span></span></button><button class="kpi warn" data-filter-link="atrasados"><span class="kpi-icon">!</span><span><span class="kpi-label">Atrasados</span><span class="kpi-value">${late.length}</span><span class="kpi-sub">${pendingExpenses?`${fmtMoney(pendingExpenses)} em despesas pendentes`:"Nenhuma despesa pendente"}</span></span></button></section><section class="panel"><div class="panel-head"><h2>Precisa de atenção</h2><a href="#pedidos">Ver todos</a></div><div class="panel-body table-wrap">${attention.length?`<table class="table mobile-list"><thead><tr><th>Pedido</th><th>Fornecedor</th><th>Previsão</th><th>Status</th><th class="num">Falta pagar</th><th></th></tr></thead><tbody>${attention.map(row).join("")}</tbody></table>`:`<div class="empty">Tudo em ordem por aqui.</div>`}</div></section><div class="grid dashboard-lower"><section class="panel"><div class="panel-head"><h2>Chegando nos próximos 15 dias</h2></div><div class="panel-body table-wrap">${in15.length?`<table class="table mobile-list"><thead><tr><th>Pedido</th><th>Fornecedor</th><th>Previsão</th><th>Status</th><th class="num">Falta pagar</th><th></th></tr></thead><tbody>${in15.map(row).join("")}</tbody></table>`:`<div class="empty">Nenhuma chegada prevista.</div>`}</div></section><section class="panel"><div class="panel-head"><h2>Saldo por fornecedor</h2></div><div class="panel-body">${Object.entries(suppliers).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="list-row"><div class="list-title">${esc(k)}</div><strong>${fmtMoney(v)}</strong></div>`).join("")||`<div class="empty">Sem saldos pendentes.</div>`}</div></section></div>`;
    app.innerHTML=shell(content,"painel");
    $(".kpis")?.insertAdjacentHTML("beforeend",`<button class="kpi"><span class="kpi-icon">↗</span><span><span class="kpi-label">Despesas pendentes</span><span class="kpi-value">${fmtMoney(pendingExpenses)}</span><span class="kpi-sub">Custos à parte ainda não pagos</span></span></button>`);
  }

  function filteredOrders(){
    const f=state.filters;
    return state.orders.filter(o=>{
      const t=totals(o),r=receipt(o),hay=slug([o.title,o.supplier?.name,(o.items||[]).map(i=>i.product?.name).join(" "),(o.trackings||[]).map(x=>x.code).join(" ")].join(" "));
      return (!f.q||hay.includes(slug(f.q)))&&(!f.supplier||String(o.supplier_id)===f.supplier)&&(!f.status||o.status===f.status)&&(!f.open||openStatuses.has(o.status))&&(!f.mode||String(o.transport_mode_id)===f.mode)&&(!f.carrier||String(o.carrier_id)===f.carrier)&&(!f.payment||t.paymentStatus===f.payment)&&(!f.receipt||r.status===f.receipt)&&(!f.from||o.order_date>=f.from)&&(!f.to||o.order_date<=f.to)&&(!f.late||(openStatuses.has(o.status)&&o.expected_date<today()))&&(!f.tax||t.taxAwaiting)&&(!f.review||o.needs_review);
    });
  }
  function optionList(items,valueKey="id",labelKey="name",selected="",blank="Todos"){return `<option value="">${esc(blank)}</option>`+items.map(x=>`<option value="${esc(x[valueKey])}" ${String(x[valueKey])===String(selected)?"selected":""}>${esc(x[labelKey])}</option>`).join("");}
  function renderOrders(){
    const list=filteredOrders(),sum=list.reduce((a,o)=>{const t=totals(o);a.pieces+=t.pieces;a.brl+=o.currency==="USD"?t.supplierTotal*n(o.exchange_rate):t.supplierTotal;a.pending+=o.currency==="USD"?Math.max(t.pending,0)*n(o.exchange_rate):Math.max(t.pending,0);return a},{pieces:0,brl:0,pending:0});
    const card=o=>{const t=totals(o),r=receipt(o),late=openStatuses.has(o.status)&&o.expected_date&&o.expected_date<today();return `<a class="order-card" href="#pedido/${o.id}"><div><div class="order-title">${esc(o.title)}</div><div class="order-meta">${esc(o.supplier?.name||"Sem fornecedor")} • Pedido em ${fmtDate(o.order_date)}</div><div class="tag-row">${statusTag(o.status)} ${payTag(t.paymentStatus)} ${receiptTag(r.status)} ${late?tag("Atrasado","red"):""} ${t.taxAwaiting?tag("Imposto a lançar","amber"):""} ${o.needs_review?tag("Revisar","red"):""}</div></div><div><span class="small muted">Previsão</span><strong style="display:block">${fmtDate(o.expected_date)}</strong></div><div><span class="small muted">Total</span><strong style="display:block">${fmtMoney(t.supplierTotal,o.currency)}</strong></div><div><span class="small muted">Falta pagar</span><strong style="display:block">${fmtMoney(t.pending,o.currency)}</strong></div><span class="chev">›</span></a>`};
    const filters=`<div class="filters"><input class="field" id="search-orders" placeholder="Buscar título, produto, fornecedor ou rastreio" value="${esc(state.filters.q||"")}"><select class="field" data-filter="supplier">${optionList(state.catalogs.suppliers,"id","name",state.filters.supplier,"Fornecedor")}</select><select class="field" data-filter="status">${optionList(Object.entries(statusLabels).map(([id,name])=>({id,name})),"id","name",state.filters.status,"Status")}</select><button class="btn" data-action="more-filters">Mais filtros</button></div>`;
    const content=pageHead("Pedidos",`${list.length} pedido${list.length===1?"":"s"}`,`<button class="btn" data-action="export">Exportar para Excel</button><a class="btn primary" href="#novo">+ Novo pedido</a>`)+filters+`<div id="advanced-filters" class="panel ${state.filters.showMore?"":"hidden"}"><div class="form-section form-grid"><label class="col-3"><span class="field-label">Modalidade</span><select class="field" data-filter="mode">${optionList(state.catalogs.transport_modes,"id","name",state.filters.mode,"Todas")}</select></label><label class="col-3"><span class="field-label">Transportadora</span><select class="field" data-filter="carrier">${optionList(state.catalogs.carriers,"id","name",state.filters.carrier,"Todas")}</select></label><label class="col-3"><span class="field-label">Pagamento</span><select class="field" data-filter="payment">${optionList(Object.entries(paymentLabels).map(([id,name])=>({id,name})),"id","name",state.filters.payment,"Todos")}</select></label><label class="col-3"><span class="field-label">Recebimento</span><select class="field" data-filter="receipt">${optionList(Object.entries(receiptLabels).map(([id,name])=>({id,name})),"id","name",state.filters.receipt,"Todos")}</select></label><label class="col-3"><span class="field-label">De</span><input class="field" type="date" data-filter="from" value="${state.filters.from||""}"></label><label class="col-3"><span class="field-label">Até</span><input class="field" type="date" data-filter="to" value="${state.filters.to||""}"></label><label class="checkbox col-2"><input type="checkbox" data-filter="late" ${state.filters.late?"checked":""}> Atrasados</label><label class="checkbox col-2"><input type="checkbox" data-filter="tax" ${state.filters.tax?"checked":""}> Imposto a lançar</label><label class="checkbox col-2"><input type="checkbox" data-filter="review" ${state.filters.review?"checked":""}> Revisão</label><div class="col-12"><button class="link-btn" data-action="clear-filters">Limpar filtros</button></div></div></div><div class="summary-bar"><div><span class="small muted">Total estimado</span><strong>${fmtMoney(sum.brl)}</strong></div><div><span class="small muted">Falta pagar</span><strong>${fmtMoney(sum.pending)}</strong></div><div><span class="small muted">Peças</span><strong>${fmtNum(sum.pieces,0)}</strong></div></div><section class="order-cards">${list.map(card).join("")||`<div class="panel empty">Nenhum pedido encontrado.</div>`}</section>`;
    app.innerHTML=shell(content,"pedidos");
  }

  const itemTemplate=(item={})=>{const sizes=item.sizes||{};return `<div class="repeat-row item-row" data-id="${item.id||""}"><label><span class="field-label">Produto</span><input class="field item-product" list="products-list" value="${esc(item.product?.name||item.product_name||"")}" required></label><label><span class="field-label">Variação</span><select class="field item-variant">${["","Masculino","Feminino","Infantil","Kit Infantil","Goleiro"].map(v=>`<option ${v===item.variant?"selected":""}>${v}</option>`).join("")}</select></label><label><span class="field-label">Caixas</span><input class="field item-boxes calc-pieces" inputmode="decimal" value="${item.boxes??""}"></label><label><span class="field-label">Peças/caixa</span><input class="field item-ppb calc-pieces" inputmode="decimal" value="${item.pieces_per_box??""}"></label><label><span class="field-label">Grades</span><input class="field item-grids calc-pieces" inputmode="decimal" value="${item.grids??""}"></label><button type="button" class="icon-btn" data-action="remove-row" title="Remover">×</button><label><span class="field-label">Peças/grade</span><input class="field item-ppg calc-pieces" inputmode="decimal" value="${item.pieces_per_grid??12}"></label><label><span class="field-label">Total de peças</span><input class="field item-total calc-total" inputmode="numeric" value="${item.total_pieces??0}"></label><label><span class="field-label">Valor unitário</span><input class="field item-price calc-total" inputmode="decimal" value="${item.unit_price??""}"></label><label><span class="field-label">Total</span><input class="field item-line-total" value="${fmtNum(n(item.total_pieces)*n(item.unit_price))}" disabled></label><button type="button" class="btn small-btn" data-action="toggle-sizes">Tamanhos</button><div></div><div class="sizes-box ${Object.keys(sizes).length?"":"hidden"}"><div class="sizes-grid">${["PP","P","M","G","GG","XGG","2XGG","3XGG"].map(s=>`<label><span class="field-label">${s}</span><input class="field size-input" data-size="${s}" inputmode="numeric" value="${sizes[s]??""}"></label>`).join("")}</div><div class="small size-warning"></div></div></div>`};
  const expenseTemplate=(e={})=>`<div class="repeat-row expense-row" data-id="${e.id||""}"><label><span class="field-label">Descrição</span><input class="field expense-description" value="${esc(e.description||"")}" required></label><label><span class="field-label">Valor</span><input class="field expense-amount" inputmode="decimal" value="${e.amount??""}"></label><label><span class="field-label">Moeda</span><select class="field expense-currency"><option ${e.currency==="USD"?"selected":""}>USD</option><option ${e.currency!=="USD"?"selected":""}>BRL</option></select></label><label class="checkbox"><input type="checkbox" class="expense-supplier" ${e.charged_by_supplier?"checked":""}> Cobrada pelo fornecedor</label><label class="checkbox"><input type="checkbox" class="expense-paid" ${e.paid?"checked":""}> Já paga</label><button type="button" class="icon-btn" data-action="remove-row">×</button></div>`;
  function renderOrderForm(id=null){
    const o=id?state.orders.find(x=>String(x.id)===String(id)):null,rate=rateFor(o?.order_date||today());
    const v=(k,d="")=>o?.[k]??d, items=o?.items?.length?o.items:[{}], expenses=o?.expenses||[];
    const content=pageHead(o?"Editar pedido":"Novo pedido",o?`Pedido #${o.id}`:"Preencha os dados principais e os itens",`<a class="btn" href="${o?`#pedido/${o.id}`:"#pedidos"}">Cancelar</a><button class="btn primary" type="submit" form="order-form">Salvar pedido</button>`)+`<form id="order-form" data-id="${o?.id||""}" class="panel"><section class="form-section form-grid"><label class="col-6"><span class="field-label">Título</span><input class="field" name="title" value="${esc(v("title"))}" required></label><label class="col-6"><span class="field-label">Fornecedor</span><input class="field" name="supplier_name" list="suppliers-list" value="${esc(o?.supplier?.name||"")}" placeholder="Escolha ou digite um novo"></label><label class="col-3"><span class="field-label">Data do pedido</span><input class="field" name="order_date" type="date" value="${v("order_date",today())}"></label><label class="col-3"><span class="field-label">Previsão</span><input class="field" name="expected_date" type="date" value="${v("expected_date")}"></label><label class="col-3"><span class="field-label">Modalidade</span><input class="field" name="transport_mode_name" list="modes-list" value="${esc(o?.transport_mode?.name||"")}" placeholder="Escolha ou digite"></label><label class="col-3"><span class="field-label">Transportadora</span><input class="field" name="carrier_name" list="carriers-list" value="${esc(o?.carrier?.name||"")}" placeholder="Escolha ou digite"></label><label class="col-3"><span class="field-label">Moeda</span><select class="field" name="currency"><option ${v("currency","USD")==="USD"?"selected":""}>USD</option><option ${v("currency")==="BRL"?"selected":""}>BRL</option></select></label><label class="col-3"><span class="field-label">Cotação</span><input class="field" name="exchange_rate" inputmode="decimal" value="${v("exchange_rate",rate?.usd_brl||"")}"></label><label class="col-3"><span class="field-label">Status</span><select class="field" name="status">${Object.entries(statusLabels).map(([k,l])=>`<option value="${k}" ${v("status","confirmado")===k?"selected":""}>${l}</option>`).join("")}</select></label><label class="checkbox col-3"><input type="checkbox" name="needs_review" ${v("needs_review")?"checked":""}> Precisa de revisão</label><label class="col-3"><span class="field-label">Frete</span><input class="field order-calc" name="freight" inputmode="decimal" value="${v("freight",0)}"></label><label class="col-3"><span class="field-label">Desconto</span><input class="field order-calc" name="discount" inputmode="decimal" value="${v("discount",0)}"></label><label class="col-3"><span class="field-label">Imposto</span><select class="field" name="tax_mode"><option value="sem" ${v("tax_mode","sem")==="sem"?"selected":""}>Sem imposto</option><option value="incluso" ${v("tax_mode")==="incluso"?"selected":""}>Incluso no pedido</option><option value="por_fora" ${v("tax_mode")==="por_fora"?"selected":""}>Pago por fora</option></select></label><label class="col-3"><span class="field-label">Valor do imposto incluso</span><input class="field" name="tax_amount" inputmode="decimal" value="${v("tax_amount",0)}"></label><label class="col-12"><span class="field-label">Observações</span><textarea class="field" name="notes">${esc(v("notes"))}</textarea></label></section><section class="form-section"><div class="panel-head" style="padding:0 0 10px"><h2>Itens</h2><button type="button" class="btn small-btn" data-action="add-item">+ Adicionar item</button></div><div id="items-list">${items.map(itemTemplate).join("")}</div></section><section class="form-section"><div class="panel-head" style="padding:0 0 10px"><h2>Outras despesas</h2><button type="button" class="btn small-btn" data-action="add-expense">+ Adicionar despesa</button></div><div id="expenses-list">${expenses.map(expenseTemplate).join("")}</div></section></form><datalist id="suppliers-list">${state.catalogs.suppliers.map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist><datalist id="products-list">${state.catalogs.products.map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist><datalist id="modes-list">${state.catalogs.transport_modes.map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist><datalist id="carriers-list">${state.catalogs.carriers.map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist><div class="sticky-total" id="form-totals"></div>`;
    app.innerHTML=shell(content,o?"pedidos":"novo"); updateFormTotals();
  }

  function renderOrderDetail(id){
    const o=state.orders.find(x=>String(x.id)===String(id)); if(!o){location.hash="#pedidos";return} const t=totals(o),r=receipt(o),tab=state.detailTab;
    const tabs=[["resumo","Resumo"],["pagamentos","Pagamentos"],["impostos","Impostos"],["rastreios","Rastreios"],["conferencia","Conferência"]];
    let body="";
    if(tab==="resumo") body=`<section class="form-section"><div class="stat-list"><div class="mini-stat"><small>Total ao fornecedor</small><strong>${fmtMoney(t.supplierTotal,o.currency)}</strong></div><div class="mini-stat"><small>Pago</small><strong>${fmtMoney(t.paid,o.currency)}</strong></div><div class="mini-stat"><small>Falta pagar</small><strong>${fmtMoney(t.pending,o.currency)}</strong></div><div class="mini-stat"><small>Custo real por peça</small><strong>${t.costPerPiece?fmtMoney(t.costPerPiece):"—"}</strong></div></div></section><section class="form-section"><h3 class="section-title">Itens</h3><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Variação</th><th class="num">Peças</th><th class="num">Unitário</th><th class="num">Total</th><th>Tamanhos</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.product?.name||"—")}</td><td>${esc(i.variant||"—")}</td><td class="num">${fmtNum(i.total_pieces,0)}</td><td class="num">${fmtMoney(i.unit_price,o.currency)}</td><td class="num"><strong>${fmtMoney(n(i.total_pieces)*n(i.unit_price),o.currency)}</strong></td><td>${esc(Object.entries(i.sizes||{}).map(([s,q])=>`${s}: ${q}`).join(" · ")||"—")}</td></tr>`).join("")}</tbody></table></div></section><section class="form-section"><h3 class="section-title">Outras despesas</h3>${o.expenses.length?o.expenses.map(e=>`<div class="list-row"><div><div class="list-title">${esc(e.description)}</div><div class="list-sub">${e.charged_by_supplier?"Cobrada pelo fornecedor":e.paid?"Paga à parte":"Pendente à parte"}</div></div><strong>${fmtMoney(e.amount,e.currency)}</strong></div>`).join(""):`<div class="muted">Nenhuma despesa.</div>`}</section>`;
    if(tab==="pagamentos") body=`<section class="form-section"><div class="panel-head" style="padding:0 0 12px"><div><h2>Pagamentos ao fornecedor</h2><p class="muted">Cada pagamento usa sua própria cotação.</p></div><button class="btn primary" data-action="payment-modal">+ Lançar pagamento</button></div><div class="stat-list"><div class="mini-stat"><small>Total</small><strong>${fmtMoney(t.supplierTotal,o.currency)}</strong></div><div class="mini-stat"><small>Pago</small><strong>${fmtMoney(t.paid,o.currency)}</strong></div><div class="mini-stat"><small>Falta</small><strong>${fmtMoney(t.pending,o.currency)}</strong></div><div class="mini-stat"><small>Situação</small><strong>${paymentLabels[t.paymentStatus]}</strong></div></div>${o.payments.map(p=>`<div class="list-row"><div><div class="list-title">${fmtDate(p.paid_on)} · ${esc(p.method?.name||"Sem forma")}</div><div class="list-sub">Cotação ${fmtNum(p.exchange_rate,4)} ${p.notes?`· ${esc(p.notes)}`:""}</div></div><div><strong>${fmtMoney(p.amount,p.currency)}</strong> ${isAdmin()?`<button class="icon-btn" data-delete="payments" data-id="${p.id}">×</button>`:""}</div></div>`).join("")||`<div class="empty">Nenhum pagamento lançado.</div>`}</section>`;
    if(tab==="impostos") body=`<section class="form-section"><div class="panel-head" style="padding:0 0 12px"><div><h2>Impostos pagos</h2><p class="muted">${o.tax_mode==="por_fora"?"Impostos pagos por fora":"Este pedido não está marcado como imposto pago por fora."}</p></div><button class="btn primary" data-action="tax-modal">+ Lançar imposto pago</button></div>${t.taxAwaiting?`<div class="alert">Imposto a lançar: ainda não há nenhum pagamento de imposto neste pedido.</div>`:""}${o.tax_payments.map(x=>{const tr=o.trackings.find(t=>String(t.id)===String(x.tracking_id));return `<div class="list-row"><div><div class="list-title">${fmtDate(x.paid_on)} ${tr?`· ${esc(tr.code)}`:"· Pedido todo"}</div><div class="list-sub">Cotação ${fmtNum(x.exchange_rate,4)} ${x.notes?`· ${esc(x.notes)}`:""}</div></div><div><strong>${fmtMoney(x.amount,x.currency)}</strong> ${isAdmin()?`<button class="icon-btn" data-delete="tax_payments" data-id="${x.id}">×</button>`:""}</div></div>`}).join("")||`<div class="empty">Nenhum imposto lançado.</div>`}</section>`;
    if(tab==="rastreios") {const counts={};o.trackings.forEach(x=>counts[x.status]=(counts[x.status]||0)+1);body=`<section class="form-section"><div class="panel-head" style="padding:0 0 12px"><div><h2>Rastreios</h2><div class="tag-row">${Object.entries(counts).map(([s,c])=>tag(`${trackingLabels[s]}: ${c}`,s==="entregue"?"green":"blue")).join("")}</div></div><button class="btn primary" data-action="tracking-modal">+ Adicionar códigos</button></div><div class="list-row"><label style="flex:1"><span class="field-label">Mudar status dos selecionados</span><select class="field" id="bulk-tracking-status">${Object.entries(trackingLabels).map(([k,l])=>`<option value="${k}">${l}</option>`).join("")}</select></label><button class="btn" data-action="bulk-tracking">Aplicar</button></div>${o.trackings.map(x=>{const carrier=x.carrier||state.catalogs.carriers.find(c=>c.id===x.carrier_id),url=(carrier?.tracking_url||"https://t.17track.net/pt#nums={code}").replace("{code}",encodeURIComponent(x.code));return `<div class="list-row"><div style="display:flex;align-items:center;gap:10px"><input type="checkbox" class="tracking-check" value="${x.id}"><div><a class="list-title" href="${esc(url)}" target="_blank" rel="noopener">${esc(x.code)} ↗</a><div class="list-sub">${esc(x.label||"Sem conteúdo")} · ${esc(carrier?.name||"17TRACK")}</div></div></div><div>${tag(trackingLabels[x.status],x.status==="entregue"?"green":"blue")} <button class="btn small-btn" data-action="toggle-tracking-received" data-id="${x.id}">${x.received?"Recebido ✓":"Marcar recebido"}</button> ${isAdmin()?`<button class="icon-btn" data-delete="trackings" data-id="${x.id}">×</button>`:""}</div></div>`}).join("")||`<div class="empty">Nenhum rastreio.</div>`}</section>`}
    if(tab==="conferencia") body=`<section class="form-section"><div class="panel-head" style="padding:0 0 12px"><div><h2>Conferência no recebimento</h2><div class="tag-row">${receiptTag(r.status)} ${tag(`${fmtNum(r.received,0)} de ${fmtNum(r.expected,0)} peças`,"blue")} ${r.defective?tag(`${r.defective} com defeito`,"red"):""}</div></div><button class="btn" data-action="receive-all">Recebi tudo</button></div>${o.items.map(i=>`<div class="receipt-row list-row" data-id="${i.id}" style="align-items:flex-end"><div class="list-main"><div class="list-title">${esc(i.product?.name||"Produto")} · ${esc(i.variant||"")}</div><div class="list-sub">Esperado: ${fmtNum(i.total_pieces,0)} ${Object.keys(i.sizes||{}).length?`· ${esc(Object.entries(i.sizes).map(([s,q])=>`${s}: ${q}`).join(" · "))}`:""}</div></div><label><span class="field-label">Recebido</span><input class="field received-qty" inputmode="numeric" value="${i.received_qty??""}" style="width:100px"></label><label><span class="field-label">Defeito</span><input class="field defective-qty" inputmode="numeric" value="${i.defective_qty??0}" style="width:90px"></label><label><span class="field-label">Observação</span><input class="field check-notes" value="${esc(i.check_notes||"")}"></label></div>`).join("")}<div style="margin-top:15px;display:flex;gap:10px;justify-content:flex-end"><label class="checkbox"><input type="checkbox" id="update-order-status" checked> Atualizar status do pedido</label><button class="btn primary" data-action="save-receipt">Salvar conferência</button></div></section>`;
    const content=`<div class="page-head"><div><a href="#pedidos" class="small">← Pedidos</a><h1>${esc(o.title)}</h1><div class="tag-row">${statusTag(o.status)} ${payTag(t.paymentStatus)} ${receiptTag(r.status)} ${t.taxAwaiting?tag("Imposto a lançar","amber"):""}</div></div><div class="head-actions"><a class="btn" href="#editar/${o.id}">Editar</a>${isAdmin()?`<button class="btn danger" data-delete="orders" data-id="${o.id}">Excluir pedido</button>`:""}</div></div><section class="panel"><div class="form-section detail-hero"><div><div class="small muted">Fornecedor</div><h2 style="margin:2px 0 12px">${esc(o.supplier?.name||"Sem fornecedor")}</h2><div class="muted">Pedido: ${fmtDate(o.order_date)} · Previsão: ${fmtDate(o.expected_date)} · ${esc(o.transport_mode?.name||"Sem modalidade")}</div>${o.notes?`<p>${esc(o.notes)}</p>`:""}</div><div><div class="small muted">Total ao fornecedor</div><div style="font-size:30px;font-weight:800">${fmtMoney(t.supplierTotal,o.currency)}</div><div class="muted">≈ ${fmtMoney(convert(t.supplierTotal,o.currency,o.currency==="USD"?"BRL":"USD",o.exchange_rate)||0,o.currency==="USD"?"BRL":"USD")}</div></div></div><div class="tabs">${tabs.map(([k,l])=>`<button data-tab="${k}" class="${tab===k?"active":""}">${l}</button>`).join("")}</div>${body}</section>`;
    app.innerHTML=shell(content,"pedidos");
    if(tab==="rastreios") $$("[data-action='toggle-tracking-received']").forEach(b=>b.insertAdjacentHTML("beforebegin",`<button class="btn small-btn" data-action="edit-tracking" data-id="${b.dataset.id}">Editar</button> `));
    if(tab==="conferencia") {
      $$(".receipt-row").forEach(row=>{const item=o.items.find(i=>i.id===Number(row.dataset.id));if(!Object.keys(item.sizes||{}).length)return;row.style.flexWrap="wrap";row.insertAdjacentHTML("beforeend",`<div class="sizes-box" style="flex-basis:100%"><span class="field-label">Recebido por tamanho</span><div class="sizes-grid">${Object.keys(item.sizes).map(s=>`<label><span class="field-label">${esc(s)}</span><input class="field received-size" data-size="${esc(s)}" inputmode="numeric" value="${item.received_sizes?.[s]??""}"></label>`).join("")}</div></div>`)});
      $("[data-action='receive-all']")?.insertAdjacentHTML("afterend",`<button class="btn" data-action="receive-packages">Marcar todos os pacotes recebidos</button>`);
    }
  }

  function renderDollar(){const r=rateFor(),fresh=r?.day===today();const content=pageHead("Dólar","Defina quantos reais valem 1 dólar em cada dia")+`<div class="grid dashboard-lower"><section class="panel"><div class="panel-head"><h2>Cotação atual</h2>${tag(fresh?"Definida hoje":"Usando a última anterior",fresh?"green":"amber")}</div><div class="form-section"><div style="font-size:38px;font-weight:800">${r?`$ 1 = ${fmtMoney(r.usd_brl)}`:"Sem cotação"}</div><p class="muted">${r?`Cotação de ${fmtDate(r.day)}`:"Cadastre a primeira cotação."}</p></div><form id="rate-form" class="form-section form-grid"><label class="col-6"><span class="field-label">Dia</span><input class="field" name="day" type="date" value="${today()}" required></label><label class="col-6"><span class="field-label">R$ por US$ 1</span><input class="field" name="usd_brl" inputmode="decimal" required></label><div class="col-12"><button class="btn primary">Salvar cotação</button></div></form></section><section class="panel"><div class="panel-head"><h2>Histórico</h2></div><div class="panel-body">${state.rates.map(x=>`<div class="list-row"><span>${fmtDate(x.day)}</span><strong>${fmtMoney(x.usd_brl)}</strong></div>`).join("")||`<div class="empty">Nenhuma cotação.</div>`}</div></section></div>`;app.innerHTML=shell(content,"dolar")}

  const registryConfig={suppliers:{title:"Fornecedores",fields:[["name","Nome"],["contact","Contato"],["notes","Observações"]]},products:{title:"Produtos",fields:[["name","Nome"],["notes","Observações"]]},transport_modes:{title:"Modalidades de transporte",fields:[["name","Nome"],["default_days","Prazo médio em dias","number"]]},carriers:{title:"Transportadoras",fields:[["name","Nome"],["tracking_url","Link de rastreio com {code}"]]},payment_methods:{title:"Formas de pagamento",fields:[["name","Nome"]]}};
  function renderRegistries(){const content=pageHead("Cadastros","Fornecedores, produtos e opções usadas nos pedidos")+`<div class="grid dashboard-lower">${Object.entries(registryConfig).map(([table,cfg])=>`<section class="panel"><div class="panel-head"><h2>${cfg.title}</h2><button class="btn small-btn" data-action="registry-modal" data-table="${table}">+ Adicionar</button></div><div class="panel-body">${state.catalogs[table].map(x=>`<div class="list-row"><div><div class="list-title">${esc(x.name)}</div><div class="list-sub">${esc(x.contact||x.notes||(x.default_days?`${x.default_days} dias`:"")||x.tracking_url||"")}</div></div><div><button class="btn small-btn" data-action="registry-modal" data-table="${table}" data-id="${x.id}">Editar</button> ${isAdmin()?`<button class="icon-btn" data-delete="${table}" data-id="${x.id}">×</button>`:""}</div></div>`).join("")||`<div class="empty">Nenhum cadastro.</div>`}</div></section>`).join("")}</div>`;app.innerHTML=shell(content,"cadastros")}

  function updateFormTotals(){
    const form=$("#order-form"); if(!form)return; let pieces=0,products=0; $$(".item-row",form).forEach(row=>{const total=n($(".item-total",row).value),price=n($(".item-price",row).value);pieces+=total;products+=total*price;$(".item-line-total",row).value=fmtNum(total*price);const sizes=$$(".size-input",row).reduce((s,x)=>s+n(x.value),0),w=$(".size-warning",row);if(w)w.innerHTML=sizes&&sizes!==total?`<span class="danger-text">A soma dos tamanhos (${fmtNum(sizes,0)}) é diferente do total (${fmtNum(total,0)}).</span>`:sizes?`<span class="success-text">Soma dos tamanhos confere.</span>`:""});
    const cur=form.currency.value,rate=n(form.exchange_rate.value),freight=n(form.freight.value),discount=n(form.discount.value);let supplierExpenses=0;$$(`.expense-row`,form).forEach(row=>{if($(".expense-supplier",row).checked)supplierExpenses+=convert(n($(".expense-amount",row).value),$(".expense-currency",row).value,cur,rate)||0});const total=products+freight-discount+supplierExpenses,other=convert(total,cur,cur==="USD"?"BRL":"USD",rate);
    $("#form-totals").innerHTML=`<div><span>Total de peças</span><strong>${fmtNum(pieces,0)}</strong></div><div><span>Total dos produtos</span><strong>${fmtMoney(products,cur)}</strong></div><div><span>Total ao fornecedor</span><strong>${fmtMoney(total,cur)}</strong></div><div><span>Conversão</span><strong>${other===null?"Informe a cotação":`≈ ${fmtMoney(other,cur==="USD"?"BRL":"USD")}`}</strong></div>`;
  }
  async function ensureNamed(table,name,extras={}){if(!name)return null;const existing=state.catalogs[table].find(x=>slug(x.name)===slug(name));if(existing)return existing;if(DEMO){const x={id:Date.now(),name,...extras};state.catalogs[table].push(x);return x}return await query(supabase.from(table).insert({name,...extras}).select().single())}
  async function saveOrder(form){
    const btn=$(`[form="order-form"]`),old=btn.textContent;btn.disabled=true;btn.textContent="Salvando…";
    try{
      const fd=new FormData(form), supplier=await ensureNamed("suppliers",fd.get("supplier_name")),mode=await ensureNamed("transport_modes",fd.get("transport_mode_name")),carrier=await ensureNamed("carriers",fd.get("carrier_name"));
      const payload={title:String(fd.get("title")).trim(),supplier_id:supplier?.id||null,order_date:fd.get("order_date")||null,expected_date:fd.get("expected_date")||null,transport_mode_id:mode?.id||null,carrier_id:carrier?.id||null,currency:fd.get("currency"),exchange_rate:dbNum(fd.get("exchange_rate")),freight:n(fd.get("freight")),discount:n(fd.get("discount")),tax_mode:fd.get("tax_mode"),tax_amount:n(fd.get("tax_amount")),status:fd.get("status"),notes:fd.get("notes")||null,needs_review:fd.get("needs_review")==="on",created_by_id:null,updated_at:new Date().toISOString()};
      const itemRows=$$(".item-row",form),items=[];for(let position=0;position<itemRows.length;position++){const row=itemRows[position],product=await ensureNamed("products",$(".item-product",row).value);if(!product)continue;const sizes={};$$('.size-input',row).forEach(x=>{if(x.value!=="")sizes[x.dataset.size]=n(x.value)});items.push({id:row.dataset.id?Number(row.dataset.id):undefined,product_id:product.id,variant:$(".item-variant",row).value||null,boxes:dbNum($(".item-boxes",row).value),pieces_per_box:dbNum($(".item-ppb",row).value),grids:dbNum($(".item-grids",row).value),pieces_per_grid:dbNum($(".item-ppg",row).value),total_pieces:n($(".item-total",row).value),unit_price:n($(".item-price",row).value),sizes:Object.keys(sizes).length?sizes:null,position})}
      const expenseRows=$$(".expense-row",form),expenses=expenseRows.filter(row=>$(".expense-description",row).value.trim()).map(row=>({id:row.dataset.id?Number(row.dataset.id):undefined,description:$(".expense-description",row).value.trim(),amount:n($(".expense-amount",row).value),currency:$(".expense-currency",row).value,charged_by_supplier:$(".expense-supplier",row).checked,paid:$(".expense-paid",row).checked}));
      if(!payload.title)throw new Error("Informe o título do pedido."); if(!items.length)throw new Error("Adicione pelo menos um item.");
      if(DEMO){showToast("No modo demonstração, os dados não são enviados ao Supabase.");location.hash="#pedidos";return}
      const id=form.dataset.id?Number(form.dataset.id):null;let saved;if(id){saved=await query(supabase.from("orders").update(payload).eq("id",id).select().single())}else{saved=await query(supabase.from("orders").insert(payload).select().single())}
      const orderId=saved.id,oldOrder=id?state.orders.find(x=>x.id===id):null;
      const keptItemIds=items.filter(x=>x.id).map(x=>x.id),keptExpenseIds=expenses.filter(x=>x.id).map(x=>x.id);
      if(id&&isAdmin()){const removeItems=(oldOrder?.items||[]).map(x=>x.id).filter(x=>!keptItemIds.includes(x));const removeExpenses=(oldOrder?.expenses||[]).map(x=>x.id).filter(x=>!keptExpenseIds.includes(x));if(removeItems.length)await query(supabase.from("order_items").delete().in("id",removeItems));if(removeExpenses.length)await query(supabase.from("order_expenses").delete().in("id",removeExpenses))}
      for(const x of items){const body={...x,order_id:orderId};delete body.id;if(x.id)await query(supabase.from("order_items").update(body).eq("id",x.id));else await query(supabase.from("order_items").insert(body))}
      for(const x of expenses){const body={...x,order_id:orderId};delete body.id;if(x.id)await query(supabase.from("order_expenses").update(body).eq("id",x.id));else await query(supabase.from("order_expenses").insert(body))}
      await loadAll();showToast("Pedido salvo com sucesso.");location.hash=`#pedido/${orderId}`;
    }catch(e){showToast(e.message||"Não foi possível salvar.",true)}finally{btn.disabled=false;btn.textContent=old}
  }

  function modal(title,body,saveLabel="Salvar"){const wrap=document.createElement("div");wrap.className="modal-backdrop";wrap.innerHTML=`<form class="modal" id="modal-form"><div class="modal-head"><h2>${esc(title)}</h2><button type="button" class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${esc(saveLabel)}</button></div></form>`;document.body.append(wrap);return $("#modal-form")}
  function currentOrder(){const id=location.hash.split("/")[1];return state.orders.find(x=>String(x.id)===String(id))}
  function paymentModal(){const r=rateFor();const f=modal("Lançar pagamento",`<div class="form-grid"><label class="col-6"><span class="field-label">Data</span><input class="field" type="date" name="paid_on" value="${today()}" required></label><label class="col-6"><span class="field-label">Valor</span><input class="field" name="amount" inputmode="decimal" required></label><label class="col-4"><span class="field-label">Moeda</span><select class="field" name="currency"><option>USD</option><option>BRL</option></select></label><label class="col-4"><span class="field-label">Cotação</span><input class="field" name="exchange_rate" inputmode="decimal" value="${r?.usd_brl||""}"></label><label class="col-4"><span class="field-label">Forma</span><input class="field" name="method" list="methods-list"></label><label class="col-12"><span class="field-label">Observação</span><textarea class="field" name="notes"></textarea></label></div><datalist id="methods-list">${state.catalogs.payment_methods.map(x=>`<option value="${esc(x.name)}">`).join("")}</datalist>`);f.addEventListener("submit",async e=>{e.preventDefault();await submitModal(f,async fd=>{const method=await ensureNamed("payment_methods",fd.get("method"));return supabase.from("payments").insert({order_id:currentOrder().id,paid_on:fd.get("paid_on"),amount:n(fd.get("amount")),currency:fd.get("currency"),exchange_rate:dbNum(fd.get("exchange_rate")),payment_method_id:method?.id||null,notes:fd.get("notes")||null,created_by_id:null})})})}
  function taxModal(){const o=currentOrder(),r=rateFor();const f=modal("Lançar imposto pago",`<div class="form-grid"><label class="col-6"><span class="field-label">Data</span><input class="field" type="date" name="paid_on" value="${today()}" required></label><label class="col-6"><span class="field-label">Valor</span><input class="field" name="amount" inputmode="decimal" required></label><label class="col-4"><span class="field-label">Moeda</span><select class="field" name="currency"><option>BRL</option><option>USD</option></select></label><label class="col-4"><span class="field-label">Cotação</span><input class="field" name="exchange_rate" inputmode="decimal" value="${r?.usd_brl||""}"></label><label class="col-4"><span class="field-label">Referente a</span><select class="field" name="tracking_id"><option value="">Pedido todo</option>${o.trackings.map(x=>`<option value="${x.id}">${esc(x.code)}</option>`).join("")}</select></label><label class="col-12"><span class="field-label">Observação</span><textarea class="field" name="notes"></textarea></label></div>`);f.addEventListener("submit",e=>{e.preventDefault();submitModal(f,fd=>supabase.from("tax_payments").insert({order_id:o.id,tracking_id:fd.get("tracking_id")?Number(fd.get("tracking_id")):null,paid_on:fd.get("paid_on"),amount:n(fd.get("amount")),currency:fd.get("currency"),exchange_rate:dbNum(fd.get("exchange_rate")),notes:fd.get("notes")||null,created_by_id:null}))})}
  function trackingModal(){const f=modal("Adicionar rastreios",`<label><span class="field-label">Códigos (um por linha, espaço ou vírgula)</span><textarea class="field" name="codes" required></textarea></label><div class="form-grid" style="margin-top:12px"><label class="col-6"><span class="field-label">Conteúdo opcional</span><input class="field" name="label" placeholder="Ex.: Internacional"></label><label class="col-6"><span class="field-label">Transportadora</span><select class="field" name="carrier_id">${optionList(state.catalogs.carriers,"id","name","","Padrão 17TRACK")}</select></label><label class="col-12"><span class="field-label">Status inicial</span><select class="field" name="status">${Object.entries(trackingLabels).map(([k,l])=>`<option value="${k}">${l}</option>`).join("")}</select></label></div>`,"Adicionar");f.addEventListener("submit",async e=>{e.preventDefault();const fd=new FormData(f),o=currentOrder(),existing=new Set(o.trackings.map(x=>x.code.trim().toUpperCase())),codes=[...new Set(String(fd.get("codes")).split(/[\s,;]+/).map(x=>x.trim().toUpperCase()).filter(x=>x&&!existing.has(x)))];if(!codes.length){showToast("Todos os códigos já existem.",true);return}await submitModal(f,()=>supabase.from("trackings").insert(codes.map(code=>({order_id:o.id,code,label:fd.get("label")||null,carrier_id:fd.get("carrier_id")?Number(fd.get("carrier_id")):null,status:fd.get("status"),received:false}))))})}
  function editTrackingModal(id){const x=currentOrder().trackings.find(t=>t.id===Number(id));const f=modal("Editar rastreio",`<div class="form-grid"><label class="col-6"><span class="field-label">Código</span><input class="field" name="code" value="${esc(x.code)}" required></label><label class="col-6"><span class="field-label">Conteúdo</span><input class="field" name="label" value="${esc(x.label||"")}"></label><label class="col-6"><span class="field-label">Transportadora</span><select class="field" name="carrier_id">${optionList(state.catalogs.carriers,"id","name",x.carrier_id,"Padrão 17TRACK")}</select></label><label class="col-6"><span class="field-label">Status</span><select class="field" name="status">${Object.entries(trackingLabels).map(([k,l])=>`<option value="${k}" ${x.status===k?"selected":""}>${l}</option>`).join("")}</select></label><label class="col-12"><span class="field-label">Observações</span><textarea class="field" name="notes">${esc(x.notes||"")}</textarea></label></div>`);f.addEventListener("submit",e=>{e.preventDefault();submitModal(f,fd=>supabase.from("trackings").update({code:String(fd.get("code")).trim(),label:fd.get("label")||null,carrier_id:fd.get("carrier_id")?Number(fd.get("carrier_id")):null,status:fd.get("status"),notes:fd.get("notes")||null}).eq("id",x.id))})}
  function registryModal(table,id){const cfg=registryConfig[table],item=state.catalogs[table].find(x=>String(x.id)===String(id))||{};const f=modal(`${item.id?"Editar":"Adicionar"} ${cfg.title.toLowerCase()}`,`<div class="form-grid">${cfg.fields.map(([name,label,type="text"])=>`<label class="col-12"><span class="field-label">${label}</span>${name==="notes"?`<textarea class="field" name="${name}">${esc(item[name]||"")}</textarea>`:`<input class="field" type="${type}" name="${name}" value="${esc(item[name]??"")}" ${name==="name"?"required":""}>`}</label>`).join("")}</div>`);f.addEventListener("submit",async e=>{e.preventDefault();const fd=new FormData(f),body={};cfg.fields.forEach(([name,,type])=>body[name]=type==="number"?dbNum(fd.get(name)):fd.get(name)||null);await submitModal(f,()=>item.id?supabase.from(table).update(body).eq("id",item.id):supabase.from(table).insert(body))})}
  async function submitModal(form,operation){const b=$("[type=submit]",form),old=b.textContent;b.disabled=true;b.textContent="Salvando…";try{if(DEMO){showToast("Ação simulada no modo demonstração.");form.closest(".modal-backdrop").remove();return}const {error}=await operation(new FormData(form));if(error)throw error;await loadAll();form.closest(".modal-backdrop").remove();showToast("Salvo com sucesso.");route()}catch(e){showToast(e.message||"Não foi possível salvar.",true)}finally{b.disabled=false;b.textContent=old}}

  async function deleteRecord(table,id){
    const labels={orders:"este pedido e todos os dados ligados a ele",payments:"este pagamento",tax_payments:"este imposto",trackings:"este rastreio",suppliers:"este fornecedor",products:"este produto",transport_modes:"esta modalidade",carriers:"esta transportadora",payment_methods:"esta forma de pagamento"};
    if(!isAdmin()){showToast("Somente o administrador pode excluir.",true);return} if(!confirm(`Tem certeza que deseja excluir ${labels[table]||"este registro"}?`))return;
    if(DEMO){showToast("Exclusão simulada no modo demonstração.");return}
    try{await query(supabase.from(table).delete().eq("id",id));await loadAll();showToast("Excluído com sucesso.");if(table==="orders")location.hash="#pedidos";else route()}catch(e){showToast(e.message||"Não foi possível excluir. Pode haver pedidos usando este cadastro.",true)}
  }
  async function saveRate(form){const fd=new FormData(form),btn=$("button",form),old=btn.textContent;btn.disabled=true;btn.textContent="Salvando…";try{if(DEMO){state.rates.unshift({day:fd.get("day"),usd_brl:n(fd.get("usd_brl"))});showToast("Cotação adicionada na demonstração.");renderDollar();return}await query(supabase.from("exchange_rates").upsert({day:fd.get("day"),usd_brl:n(fd.get("usd_brl"))},{onConflict:"day"}));await loadAll();showToast("Cotação salva.");renderDollar()}catch(e){showToast(e.message,true)}finally{btn.disabled=false;btn.textContent=old}}
  async function saveReceipt(){const o=currentOrder(),rows=$$(".receipt-row"),updates=rows.map(row=>{const received_sizes={};$$(".received-size",row).forEach(x=>{if(x.value!=="")received_sizes[x.dataset.size]=n(x.value)});return {id:Number(row.dataset.id),received_qty:dbNum($(".received-qty",row).value),defective_qty:n($(".defective-qty",row).value),check_notes:$(".check-notes",row).value||null,received_sizes:Object.keys(received_sizes).length?received_sizes:null}});if(DEMO){updates.forEach(u=>Object.assign(o.items.find(i=>i.id===u.id),u));showToast("Conferência salva na demonstração.");renderOrderDetail(o.id);return}try{for(const u of updates){const body={...u};delete body.id;await query(supabase.from("order_items").update(body).eq("id",u.id))}const temp={...o,items:o.items.map(i=>({...i,...updates.find(u=>u.id===i.id)}))},rec=receipt(temp);if($("#update-order-status")?.checked){const status=rec.status==="completo"||rec.status==="divergencia"?"recebido":rec.status==="parcial"?"recebido_parcial":o.status;await query(supabase.from("orders").update({status,updated_at:new Date().toISOString()}).eq("id",o.id))}await loadAll();showToast("Conferência salva.");renderOrderDetail(o.id)}catch(e){showToast(e.message,true)}}
  async function receiveAllPackages(){const o=currentOrder(),ids=o.trackings.filter(x=>!x.received).map(x=>x.id);if(!ids.length){showToast("Todos os pacotes já estão recebidos.");return}if(DEMO){o.trackings.forEach(x=>{x.received=true;x.received_date=today();x.status="entregue"});renderOrderDetail(o.id);return}try{await query(supabase.from("trackings").update({received:true,received_date:today(),status:"entregue"}).in("id",ids));await loadAll();renderOrderDetail(o.id);showToast("Todos os pacotes foram marcados como recebidos.")}catch(e){showToast(e.message,true)}}
  async function toggleTrackingReceived(id){const o=currentOrder(),x=o.trackings.find(t=>t.id===Number(id)),received=!x.received;if(DEMO){x.received=received;x.received_date=received?today():null;renderOrderDetail(o.id);return}try{await query(supabase.from("trackings").update({received,received_date:received?today():null,status:received?"entregue":x.status}).eq("id",id));await loadAll();renderOrderDetail(o.id)}catch(e){showToast(e.message,true)}}
  async function bulkTracking(){const ids=$$(".tracking-check:checked").map(x=>Number(x.value)),status=$("#bulk-tracking-status").value;if(!ids.length){showToast("Selecione pelo menos um rastreio.",true);return}if(DEMO){currentOrder().trackings.filter(x=>ids.includes(x.id)).forEach(x=>x.status=status);renderOrderDetail(currentOrder().id);return}try{await query(supabase.from("trackings").update({status}).in("id",ids));await loadAll();renderOrderDetail(currentOrder().id);showToast("Status atualizado.")}catch(e){showToast(e.message,true)}}
  function exportExcel(){
    if(!window.XLSX){showToast("Não foi possível carregar o recurso de Excel.",true);return}const orders=filteredOrders(),wb=XLSX.utils.book_new(),rows=orders.map(o=>{const t=totals(o),r=receipt(o);return {ID:o.id,Título:o.title,Fornecedor:o.supplier?.name||"","Data do pedido":fmtDate(o.order_date),Previsão:fmtDate(o.expected_date),Status:statusLabels[o.status],Moeda:o.currency,Cotação:n(o.exchange_rate),"Total fornecedor":t.supplierTotal,Pago:t.paid,"Falta pagar":t.pending,"Situação pagamento":paymentLabels[t.paymentStatus],"Situação recebimento":receiptLabels[r.status],Peças:t.pieces,"Custo total R$":t.landedBRL,"Custo/peça R$":t.costPerPiece||0,"Precisa revisão":o.needs_review?"Sim":"Não"}});
    const add=(name,data)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(data),name);add("Pedidos",rows);add("Itens",orders.flatMap(o=>o.items.map(i=>({Pedido:o.title,Produto:i.product?.name||"",Variação:i.variant||"",Caixas:n(i.boxes),"Peças/caixa":n(i.pieces_per_box),Grades:n(i.grids),"Peças/grade":n(i.pieces_per_grid),"Total peças":n(i.total_pieces),"Valor unitário":n(i.unit_price),Tamanhos:Object.entries(i.sizes||{}).map(([s,q])=>`${s}:${q}`).join("; ")}))));add("Pagamentos",orders.flatMap(o=>o.payments.map(p=>({Pedido:o.title,Data:fmtDate(p.paid_on),Valor:n(p.amount),Moeda:p.currency,Cotação:n(p.exchange_rate),Forma:p.method?.name||"",Observação:p.notes||""}))));add("Impostos",orders.flatMap(o=>o.tax_payments.map(x=>({Pedido:o.title,Rastreio:o.trackings.find(t=>t.id===x.tracking_id)?.code||"Pedido todo",Data:fmtDate(x.paid_on),Valor:n(x.amount),Moeda:x.currency,Cotação:n(x.exchange_rate),Observação:x.notes||""}))));add("Rastreios",orders.flatMap(o=>o.trackings.map(x=>({Pedido:o.title,Código:x.code,Conteúdo:x.label||"",Transportadora:x.carrier?.name||"",Status:trackingLabels[x.status],Recebido:x.received?"Sim":"Não","Data recebimento":fmtDate(x.received_date)}))));XLSX.writeFile(wb,`encomendas-${today()}.xlsx`);
  }
  function readFilter(el){const k=el.dataset.filter;state.filters[k]=el.type==="checkbox"?el.checked:el.value;renderOrders()}
  let searchTimer;
  function bindEvents(){
    document.addEventListener("submit",async e=>{if(e.target.id==="login-form"){e.preventDefault();const fd=new FormData(e.target),b=$("button",e.target);b.disabled=true;b.textContent="Entrando…";const {error}=await supabase.auth.signInWithPassword({email:fd.get("email"),password:fd.get("password")});if(error){renderLogin("E-mail ou senha incorretos.")}return}if(e.target.id==="order-form"){e.preventDefault();saveOrder(e.target)}if(e.target.id==="rate-form"){e.preventDefault();saveRate(e.target)}});
    document.addEventListener("input",e=>{if(e.target.id==="search-orders"){clearTimeout(searchTimer);state.filters.q=e.target.value;searchTimer=setTimeout(renderOrders,250)}if(e.target.closest("#order-form")){const row=e.target.closest(".item-row");if(row&&e.target.classList.contains("calc-pieces")){const boxes=n($(".item-boxes",row).value),ppb=n($(".item-ppb",row).value),grids=n($(".item-grids",row).value),ppg=n($(".item-ppg",row).value);$(".item-total",row).value=Math.round(boxes*ppb+grids*ppg)}updateFormTotals()}});
    document.addEventListener("change",e=>{if(e.target.dataset.filter)readFilter(e.target);if(e.target.name==="transport_mode_name"){const mode=state.catalogs.transport_modes.find(x=>slug(x.name)===slug(e.target.value)),form=e.target.form;if(mode&&form.order_date.value&&!form.expected_date.value)form.expected_date.value=addDays(form.order_date.value,mode.default_days)}if(e.target.closest("#order-form"))updateFormTotals()});
    document.addEventListener("click",async e=>{
      const del=e.target.closest("[data-delete]");if(del){e.preventDefault();deleteRecord(del.dataset.delete,Number(del.dataset.id));return}
      const tab=e.target.closest("[data-tab]");if(tab){state.detailTab=tab.dataset.tab;renderOrderDetail(currentOrder().id);return}
      const action=e.target.closest("[data-action]")?.dataset.action;if(!action)return;
      if(action==="logout"){if(DEMO){location.href=location.pathname}else await supabase.auth.signOut()}
      if(action==="more-filters"){state.filters.showMore=!state.filters.showMore;renderOrders()}
      if(action==="clear-filters"){state.filters={showMore:true};renderOrders()}
      if(action==="export")exportExcel();
      if(action==="add-item"){e.preventDefault();$("#items-list").insertAdjacentHTML("beforeend",itemTemplate());updateFormTotals()}
      if(action==="add-expense"){e.preventDefault();$("#expenses-list").insertAdjacentHTML("beforeend",expenseTemplate())}
      if(action==="remove-row"){const row=e.target.closest(".repeat-row");if(row.dataset.id&&!isAdmin()){showToast("Somente o administrador pode excluir um item já salvo.",true);return}row.remove();updateFormTotals()}
      if(action==="toggle-sizes")e.target.closest(".item-row").querySelector(".sizes-box").classList.toggle("hidden");
      if(action==="close-modal")e.target.closest(".modal-backdrop").remove();
      if(action==="payment-modal")paymentModal();if(action==="tax-modal")taxModal();if(action==="tracking-modal")trackingModal();if(action==="edit-tracking")editTrackingModal(e.target.dataset.id);if(action==="registry-modal")registryModal(e.target.closest("[data-table]").dataset.table,e.target.closest("[data-id]")?.dataset.id);
      if(action==="toggle-tracking-received")toggleTrackingReceived(e.target.dataset.id);if(action==="bulk-tracking")bulkTracking();
      if(action==="receive-all"){$$(".receipt-row").forEach(row=>$(".received-qty",row).value=currentOrder().items.find(i=>i.id===Number(row.dataset.id)).total_pieces);showToast("Quantidades preenchidas. Clique em Salvar conferência.")}
      if(action==="receive-packages")receiveAllPackages();
      if(action==="save-receipt")saveReceipt();
    });
    document.addEventListener("click",e=>{const f=e.target.closest("[data-filter-link]");if(!f)return;state.filters={};if(f.dataset.filterLink==="atrasados")state.filters.late=true;if(f.dataset.filterLink==="abertos")state.filters.open=true;if(f.dataset.filterLink==="receber")state.filters.receipt="nao_recebido";location.hash="#pedidos"});
  }
  function route(){
    const raw=location.hash.replace(/^#/,"")||"painel",[name,id]=raw.split("/");state.route=name;if(!["pedido"].includes(name))state.detailTab="resumo";window.scrollTo(0,0);
    if(name==="painel")renderDashboard();else if(name==="pedidos")renderOrders();else if(name==="novo")renderOrderForm();else if(name==="editar")renderOrderForm(id);else if(name==="pedido")renderOrderDetail(id);else if(name==="dolar")renderDollar();else if(name==="cadastros")renderRegistries();else location.hash="#painel";
  }
  async function start(){
    bindEvents();window.addEventListener("hashchange",route);
    if(DEMO){await loadAll();route();return}if(!CONFIGURED){renderConfigHelp();return}
    supabase=window.supabase.createClient(CONFIG.SUPABASE_URL,CONFIG.SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    const {data:{session}}=await supabase.auth.getSession();state.session=session;if(session){try{await loadAll();route()}catch(e){renderLogin(`Não foi possível carregar os dados: ${e.message}`)}}else renderLogin();
    supabase.auth.onAuthStateChange(async(event,session)=>{state.session=session;if(event==="SIGNED_IN"&&session){try{await loadAll();route()}catch(e){renderLogin(`Acesso criado, mas o perfil ou as políticas não estão prontos: ${e.message}`)}}if(event==="SIGNED_OUT")renderLogin()});
  }
  start();
})();
